DROP TABLE IF EXISTS airport;
CREATE TABLE airport (
  airport_id serial NOT NULL,
  name varchar(255) NOT NULL,
  city varchar(255) NOT NULL,
  country varchar(255) NOT NULL,
  iata varchar(5) NOT NULL,
  icao varchar(5) NOT NULL,
  latitude varchar(20) NOT NULL,
  longitude varchar(20) NOT NULL,
  altitude integer NOT NULL,
  type varchar(20) DEFAULT NULL,
  home_link varchar(255) DEFAULT NULL,
  wikipedia_link varchar(255) DEFAULT NULL,
  image_thumb varchar(255) DEFAULT NULL,
  image varchar(255) DEFAULT NULL,
  diagram_pdf varchar(255) DEFAULT NULL,
  diagram_png varchar(255) DEFAULT NULL,
  PRIMARY KEY (airport_id),
  UNIQUE (icao)
);

